create table actuator_commands (id bigint not null auto_increment, issued_at datetime(6) not null, node_id bigint not null, action enum ('ACTIVATE','DEACTIVATE') not null, actuator_type enum ('BUZZER','LED','SERVO','UV_LIGHT','WATER_SPRAYER') not null, status enum ('ACKNOWLEDGED','EXECUTED','PENDING','SENT') not null, primary key (id)) engine=InnoDB;
create table agent_action_proposals (duration_seconds integer not null, command_expires_at datetime(6), confirmed_at datetime(6), created_at datetime(6), expires_at datetime(6), node_id bigint, owner_id bigint not null, plant_id bigint, version bigint, actuator varchar(255), command_status varchar(255), conversation_id varchar(255), id varchar(255) not null, node_code varchar(255), status varchar(255), primary key (id)) engine=InnoDB;
create table agent_conversations (created_at datetime(6), owner_id bigint not null, version bigint, id varchar(255) not null, messages_json LONGTEXT, primary key (id)) engine=InnoDB;
create table ai_quotas (quota_date date, requests integer not null, owner_id bigint not null, primary key (owner_id)) engine=InnoDB;
create table green_rewards (eligible_days integer not null, humidity_max float(23), humidity_min float(23), light_min float(23), node_id bigint, owner_id bigint, plant_id bigint, started_at datetime(6), version bigint, error_code varchar(255), id varchar(255) not null, recipient varchar(255), status varchar(255), transaction_hash varchar(255), signed_transaction LONGTEXT, primary key (id)) engine=InnoDB;
create table iot_nodes (created_at datetime(6) not null, id bigint not null auto_increment, linked_at datetime(6), plant_id bigint, profile_id bigint, reported_at datetime(6), updated_at datetime(6) not null, node_code varchar(255) not null, desired_buzzer_mode enum ('OFF','ON') not null, desired_led_mode enum ('AUTO','OFF','ON') not null, desired_servo_mode enum ('AUTO','OFF','ON') not null, reported_buzzer_mode enum ('OFF','ON') not null, reported_led_mode enum ('AUTO','OFF','ON') not null, reported_servo_mode enum ('AUTO','OFF','ON') not null, status enum ('ERROR','OFFLINE','ONLINE') not null, primary key (id)) engine=InnoDB;
create table mint_locks (id bigint not null, primary key (id)) engine=InnoDB;
create table plants (acquisition_date date, humidity_threshold_max float(23), humidity_threshold_min float(23), light_threshold_min float(23), next_watering_date date, notifications_enabled bit, temperature_threshold_max float(23), temperature_threshold_min float(23), created_at datetime(6) not null, id bigint not null auto_increment, profile_id bigint, updated_at datetime(6) not null, description varchar(255), image_url LONGTEXT, plant_name varchar(255), species varchar(255), humidity enum ('ALTA','BAJA','MEDIA'), primary key (id)) engine=InnoDB;
create table plant_analyses (created_at datetime(6), owner_id bigint not null, plant_id bigint, started_at datetime(6), version bigint, fingerprint varchar(100) not null, request_key varchar(100) not null, error_code varchar(255), id varchar(255) not null, status varchar(255) not null, image LONGBLOB, result_json LONGTEXT, primary key (id)) engine=InnoDB;
create table profiles (created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6) not null, user_id bigint, name varchar(255), payment_status enum ('PAID','PENDING'), profile_picture_base64 TEXT, subscription_plan enum ('BASIC','PREMIUM','PRO'), primary key (id)) engine=InnoDB;
create table roles (id bigint not null auto_increment, name enum ('ROLE_ADMIN','ROLE_USER'), primary key (id)) engine=InnoDB;
create table sensor_readings (air_temperature float(23), gas_percent integer, humidity_percent integer, light_percent integer, id bigint not null auto_increment, node_id bigint not null, timestamp datetime(6) not null, primary key (id)) engine=InnoDB;
create table tasks (humidity integer, scheduled_date date not null, completed_at datetime(6), created_at datetime(6) not null, id bigint not null auto_increment, plant_id bigint, profile_id bigint, updated_at datetime(6) not null, action varchar(255) not null, notes varchar(255), primary key (id)) engine=InnoDB;
create table users (created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6) not null, password varchar(120) not null, email varchar(254) not null, primary key (id)) engine=InnoDB;
create table user_roles (role_id bigint not null, user_id bigint not null, primary key (role_id, user_id)) engine=InnoDB;
create table wallet_bindings (owner_id bigint not null, verified_at datetime(6), version bigint, address varchar(255) not null, primary key (owner_id)) engine=InnoDB;
create table wallet_challenges (consumed bit not null, expires_at datetime(6), owner_id bigint, version bigint, message varchar(2000), address varchar(255), id varchar(255) not null, primary key (id)) engine=InnoDB;
